import{_ as t,o as a,c as s,a6 as n}from"./chunks/framework.4tsfTCyC.js";const u=JSON.parse('{"title":"Built-in Agent Reference","description":"","frontmatter":{},"headers":[],"relativePath":"guide/built-in-agents.md","filePath":"guide/built-in-agents.md"}'),o={name:"guide/built-in-agents.md"};function i(r,e,l,c,p,d){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="built-in-agent-reference" tabindex="-1">Built-in Agent Reference <a class="header-anchor" href="#built-in-agent-reference" aria-label="Permalink to &quot;Built-in Agent Reference&quot;">​</a></h1><p>TeXRA ships with built-in agents for common research tasks—polishing prose, fixing errors, creating figures, converting formats, and more. Pick one from the dropdown in the TeXRA UI and you&#39;re ready to go.</p><h2 id="quick-reference" tabindex="-1">Quick Reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Agent</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>chat</code></td><td>Tool-use</td><td>General assistance, file editing</td></tr><tr><td><code>ask</code></td><td>Tool-use</td><td>Read-only questions and exploration</td></tr><tr><td><code>search</code></td><td>Tool-use</td><td>Literature discovery, web search</td></tr><tr><td><code>research</code></td><td>Tool-use</td><td>Computational verification with Wolfram</td></tr><tr><td><code>discuss</code></td><td>Tool-use</td><td>Academic brainstorming with literature</td></tr><tr><td><code>lean</code></td><td>Tool-use</td><td>Lean 4 proof development</td></tr><tr><td><code>presenter</code></td><td>Tool-use</td><td>Interactive presentation builder</td></tr><tr><td><code>simplifier</code></td><td>Tool-use</td><td>Simplify code and LaTeX for clarity</td></tr><tr><td><code>correct</code></td><td>Workflow</td><td>Fix errors without style changes</td></tr><tr><td><code>polish</code></td><td>Workflow</td><td>Improve writing quality</td></tr><tr><td><code>paper2slide</code></td><td>Workflow</td><td>Convert papers to beamer slides</td></tr><tr><td><code>paper2poster</code></td><td>Workflow</td><td>Create academic posters</td></tr><tr><td><code>draw</code></td><td>Workflow</td><td>Create/enhance TikZ figures</td></tr><tr><td><code>ocr</code></td><td>Workflow</td><td>Extract text from images/PDFs</td></tr><tr><td><code>transcribe_audio</code></td><td>Workflow</td><td>Transcribe audio to text</td></tr><tr><td><code>merge</code></td><td>Workflow</td><td>Intelligently merge document versions</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Important Note</p><p>The underlying prompts and specific behaviors of these built-in agents may change slightly between TeXRA versions as we continue to optimize them. If you require precise, unchanging behavior or wish to heavily customize the process, consider creating a <a href="./custom-agents.html">Custom Agent</a> based on these examples.</p></div><p>For details on the underlying structure and execution flow common to all agents, see the <a href="./agent-architecture.html">Agent Architecture &amp; Execution Flow</a> guide.</p><h2 id="conversational-agents" tabindex="-1">Conversational Agents <a class="header-anchor" href="#conversational-agents" aria-label="Permalink to &quot;Conversational Agents&quot;">​</a></h2><h3 id="chat" tabindex="-1"><code>chat</code> <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;`chat`&quot;">​</a></h3><p>Your go-to research companion. It can read your project, edit files, run shell commands, and search through your workspace—all in a back-and-forth conversation.</p><blockquote><p><strong>User story:</strong> You just got reviewer comments back. Instead of manually hunting through a 40-page paper, you open <code>chat</code> and paste the reviewer&#39;s feedback: &quot;Address comment 3 about missing error bars in Table 2—add them and update the caption.&quot; The agent reads your files, makes the edits, and shows you a diff to approve.</p></blockquote><p><strong>Best for:</strong> General research assistance, code/LaTeX editing, running compilations</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review my introduction in paper.tex and suggest improvements for clarity.</span></span>\n<span class="line"><span>Then update the file with your changes.</span></span></code></pre></div><h3 id="ask" tabindex="-1"><code>ask</code> <a class="header-anchor" href="#ask" aria-label="Permalink to &quot;`ask`&quot;">​</a></h3><p>A read-only assistant for exploring your workspace. It can answer questions about your project without touching any files—safe to use when you just want to understand what&#39;s there.</p><p><strong>Best for:</strong> Quick questions, understanding existing code, safe exploration</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What packages does this LaTeX project use? Summarize the document structure.</span></span></code></pre></div><h2 id="research-discovery-agents" tabindex="-1">Research &amp; Discovery Agents <a class="header-anchor" href="#research-discovery-agents" aria-label="Permalink to &quot;Research &amp; Discovery Agents&quot;">​</a></h2><h3 id="search" tabindex="-1"><code>search</code> <a class="header-anchor" href="#search" aria-label="Permalink to &quot;`search`&quot;">​</a></h3><p>Finds papers and web content for you. Give it a topic and it comes back with relevant preprints, published articles, and web resources. Read-only—it won&#39;t touch your files.</p><p><strong>Best for:</strong> Literature reviews, finding citations, fact-checking</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Find recent papers on transformer architectures for scientific document understanding.</span></span>\n<span class="line"><span>Focus on papers from 2023-2024 that address mathematical equation handling.</span></span></code></pre></div><h3 id="research" tabindex="-1"><code>research</code> <a class="header-anchor" href="#research" aria-label="Permalink to &quot;`research`&quot;">​</a></h3><p>A hands-on research agent that can edit your files <strong>and</strong> verify mathematics computationally. When you need to check a derivation or run a symbolic calculation alongside your writing, this is the one.</p><p><strong>Best for:</strong> Mathematical derivations, computational verification, multi-step research</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Derive the variational equations for the Lagrangian in equations.tex.</span></span>\n<span class="line"><span>Verify each step computationally and update the file with results.</span></span></code></pre></div><h3 id="discuss" tabindex="-1"><code>discuss</code> <a class="header-anchor" href="#discuss" aria-label="Permalink to &quot;`discuss`&quot;">​</a></h3><p>A brainstorming partner that can pull in relevant literature as you talk. Useful for thinking through research directions, poking holes in methodology, or connecting ideas across papers. Read-only.</p><p><strong>Best for:</strong> Brainstorming, methodology critique, research direction guidance</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m considering attention mechanisms for my theorem prover. What are the</span></span>\n<span class="line"><span>tradeoffs compared to tree-based approaches? What does the literature say?</span></span></code></pre></div><h2 id="formal-methods-agents" tabindex="-1">Formal Methods Agents <a class="header-anchor" href="#formal-methods-agents" aria-label="Permalink to &quot;Formal Methods Agents&quot;">​</a></h2><h3 id="lean" tabindex="-1"><code>lean</code> <a class="header-anchor" href="#lean" aria-label="Permalink to &quot;`lean`&quot;">​</a></h3><p>Helps you write and debug Lean 4 proofs. It reads compiler diagnostics, inspects proof state, and iterates until the proof compiles.</p><p><strong>Best for:</strong> Formalizing proofs, Lean 4 development, Mathlib projects</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Formalize the proof of the theorem in Proofs/GroupTheory.lean. Start with an</span></span>\n<span class="line"><span>informal outline, then produce Lean code and iterate until it compiles.</span></span></code></pre></div><h2 id="presentation-simplification-agents" tabindex="-1">Presentation &amp; Simplification Agents <a class="header-anchor" href="#presentation-simplification-agents" aria-label="Permalink to &quot;Presentation &amp; Simplification Agents&quot;">​</a></h2><h3 id="presenter" tabindex="-1"><code>presenter</code> <a class="header-anchor" href="#presenter" aria-label="Permalink to &quot;`presenter`&quot;">​</a></h3><p>Builds conference-ready Beamer presentations, posters, and visual materials from your project. Point it at your paper and it reads through your work, plans the slide structure, generates figures, and compiles the result—checking every slide visually before handing it back to you.</p><p><strong>Best for:</strong> Conference talks, poster sessions, seminar presentations, lightning talks</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a 15-slide Beamer presentation from this project. Cover motivation, the core</span></span>\n<span class="line"><span>algorithm, key results, and future work. Use the metropolis theme and include TikZ</span></span>\n<span class="line"><span>diagrams for the architecture.</span></span></code></pre></div><h3 id="simplifier" tabindex="-1"><code>simplifier</code> <a class="header-anchor" href="#simplifier" aria-label="Permalink to &quot;`simplifier`&quot;">​</a></h3><p>Cuts through complexity in your code and writing. Whether it&#39;s duplicated logic across files, overly-abstract wrappers, or LLM-generated filler prose, <code>simplifier</code> cleans things up while preserving correctness.</p><p><strong>Best for:</strong> Refactoring research code, tightening manuscript prose, cleaning up verbose AI-generated text</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Simplify the numerical solver in solver.py. Look for duplicated code, inline any</span></span>\n<span class="line"><span>single-use helper functions, and remove dead code. Run existing tests after each change.</span></span></code></pre></div><h2 id="correction-polishing-agents" tabindex="-1">Correction &amp; Polishing Agents <a class="header-anchor" href="#correction-polishing-agents" aria-label="Permalink to &quot;Correction &amp; Polishing Agents&quot;">​</a></h2><h3 id="correct" tabindex="-1"><code>correct</code> <a class="header-anchor" href="#correct" aria-label="Permalink to &quot;`correct`&quot;">​</a></h3><p>The <code>correct</code> agent focuses on fixing errors without changing the style or content of your document (think of it as a meticulous, slightly obsessive proofreader).</p><p><strong>Purpose:</strong> Fix typos, grammatical errors, and LaTeX syntax issues.</p><p><strong>Best for:</strong></p><ul><li>Final proofreading before submission</li><li>Fixing errors in collaborative documents</li><li>Ensuring consistent formatting and notation</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Fix grammatical errors, typos, and LaTeX syntax issues throughout the document.</span></span>\n<span class="line"><span>Ensure consistent notation for mathematical symbols and equations.</span></span>\n<span class="line"><span>Don&#39;t change the technical content or writing style.</span></span></code></pre></div><h3 id="polish" tabindex="-1"><code>polish</code> <a class="header-anchor" href="#polish" aria-label="Permalink to &quot;`polish`&quot;">​</a></h3><p>The <code>polish</code> agent improves the writing quality of your document while preserving essential technical content and meaning.</p><blockquote><p><strong>User story:</strong> Your draft is technically solid but reads like it was written at 3 AM (because it was). Select <code>polish</code>, tell it &quot;Improve clarity for a CVPR audience—keep all equations and citations intact,&quot; and in a couple of minutes you&#39;ll have a version that reads like it went through a professional copyedit. Review the colour-coded diff to accept or reject each change.</p></blockquote><p>This agent is ideal for refining drafts that are technically sound but need language improvements before submission.</p><h4 id="example-output" tabindex="-1">Example Output <a class="header-anchor" href="#example-output" aria-label="Permalink to &quot;Example Output&quot;">​</a></h4><div class="agent-pdf-viewer"><iframe src="/examples/draft_polish_r1_gemini25p_diff.pdf" title="Polish Agent Example" class="agent-pdf-frame"></iframe><a href="/examples/draft_polish_r1_gemini25p_diff.pdf" target="_blank" class="agent-pdf-link">View example</a></div><h2 id="content-generation-transformation-agents" tabindex="-1">Content Generation &amp; Transformation Agents <a class="header-anchor" href="#content-generation-transformation-agents" aria-label="Permalink to &quot;Content Generation &amp; Transformation Agents&quot;">​</a></h2><h3 id="paper2slide" tabindex="-1"><code>paper2slide</code> <a class="header-anchor" href="#paper2slide" aria-label="Permalink to &quot;`paper2slide`&quot;">​</a></h3><p>The <code>paper2slide</code> agent converts research papers into LaTeX beamer presentations.</p><p><strong>Purpose:</strong> Create presentation slides from academic content.</p><p><strong>Best for:</strong></p><ul><li>Preparing conference presentations</li><li>Converting papers for teaching purposes</li><li>Creating seminar materials</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Convert this paper into a beamer presentation with approximately 15-20 slides.</span></span>\n<span class="line"><span>Include a title slide, outline, introduction, methodology, results, and conclusion.</span></span>\n<span class="line"><span>Use bullet points for clarity and add slide titles. Include the key figures and tables.</span></span></code></pre></div><h3 id="paper2poster" tabindex="-1"><code>paper2poster</code> <a class="header-anchor" href="#paper2poster" aria-label="Permalink to &quot;`paper2poster`&quot;">​</a></h3><p>The <code>paper2poster</code> agent transforms papers into academic conference posters.</p><p><strong>Purpose:</strong> Create well-structured academic posters.</p><p><strong>Best for:</strong></p><ul><li>Conference poster preparation</li><li>Visual research summaries</li><li>Academic showcases</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Convert this paper into an academic poster using the baposter template.</span></span>\n<span class="line"><span>Include sections for Introduction, Methodology, Results, and Conclusions.</span></span>\n<span class="line"><span>Highlight key figures and tables. Make it visually appealing with appropriate columns.</span></span></code></pre></div><h2 id="figure-media-agents" tabindex="-1">Figure &amp; Media Agents <a class="header-anchor" href="#figure-media-agents" aria-label="Permalink to &quot;Figure &amp; Media Agents&quot;">​</a></h2><h3 id="draw" tabindex="-1"><code>draw</code> <a class="header-anchor" href="#draw" aria-label="Permalink to &quot;`draw`&quot;">​</a></h3><p>Creates or enhances TikZ figures from textual descriptions or existing code.</p><blockquote><p><strong>User story:</strong> You need a neural-network architecture diagram for your paper. Describe the layers and connections in the instruction box, and <code>draw</code> generates compilable TikZ code.</p></blockquote><p><strong>Best for:</strong></p><ul><li>Creating diagrams, flowcharts, or schematics from descriptions</li><li>Improving existing TikZ figures</li><li>Converting descriptions into LaTeX visualizations</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create a TikZ figure illustrating a neural network with an input layer (3 nodes),</span></span>\n<span class="line"><span>two hidden layers (5 nodes each), and an output layer (2 nodes).</span></span>\n<span class="line"><span>Use appropriate colors and add labels for each layer.</span></span></code></pre></div><h3 id="ocr" tabindex="-1"><code>ocr</code> <a class="header-anchor" href="#ocr" aria-label="Permalink to &quot;`ocr`&quot;">​</a></h3><p>The <code>ocr</code> agent performs Optical Character Recognition (OCR) on image or PDF files.</p><p><strong>Purpose:</strong> Extract text content from images or non-searchable PDFs.</p><p><strong>Best for:</strong></p><ul><li>Extracting text from scanned documents or figures</li><li>Making image-based text searchable and editable</li><li>Processing figures containing text for analysis</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Perform OCR on the provided image file [figure.png] and extract all text content. Format the output as plain text.</span></span></code></pre></div><h3 id="transcribe-audio" tabindex="-1"><code>transcribe_audio</code> <a class="header-anchor" href="#transcribe-audio" aria-label="Permalink to &quot;`transcribe_audio`&quot;">​</a></h3><p>The <code>transcribe_audio</code> agent converts audio files (like lectures, podcasts, or personal notes) into text transcripts. (Note: Requires native audio support, see <a href="./working-with-figures.html">Working with Figures</a>).</p><p><strong>Purpose:</strong> Create searchable text versions of spoken audio content.</p><p><strong>Best for:</strong></p><ul><li>Transcribing recorded lectures or talks</li><li>Converting podcast episodes to text</li><li>Transcribing personal voice memos or notes</li></ul><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transcribe the provided lecture audio file [lecture.mp3]. Provide the output as plain text, identifying different speakers if possible (e.g., Lecturer, Questioner 1).</span></span></code></pre></div><h2 id="merge-agent" tabindex="-1">Merge Agent <a class="header-anchor" href="#merge-agent" aria-label="Permalink to &quot;Merge Agent&quot;">​</a></h2><h3 id="merge" tabindex="-1"><code>merge</code> <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;`merge`&quot;">​</a></h3><p>Takes an AI-edited document and merges the improvements back into your original, keeping the best of both. It understands context, so it won&#39;t blindly overwrite your careful phrasing with generic rewrites.</p><p><strong>Best for:</strong> Applying AI-suggested edits from output files, incorporating reviewer suggestions, combining different drafts</p><p><strong>Example instruction:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Merge changes from the edited file into the original document. Prioritize substantive</span></span>\n<span class="line"><span>improvements in clarity while maintaining the original&#39;s technical precision.</span></span>\n<span class="line"><span>Preserve mathematical notation and citations from the original.</span></span></code></pre></div><p>See <a href="./intelligent-merge.html">Intelligent Merge</a> for details on the merge workflow.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./agent-architecture.html">Agent Architecture</a> - How agents work internally</li><li><a href="./research-tools.html">Research Tools</a> - Literature discovery and web tools</li><li><a href="./custom-agents.html">Custom Agents</a> - Create your own agents</li><li><a href="./models.html">Models</a> - AI model selection</li></ul>',111)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
